@State private var position = ScrollPosition(edge: .top)

var body: some View {
    ScrollView {
        LazyVStack { ForEach(messages) { MessageRow($0) } }
    }
    .scrollPosition($position)
    .toolbar {
        Button("Latest") { position.scrollTo(edge: .bottom) }
    }
}

ScrollViewReader { proxy in
    ScrollView {
        LazyVStack {
            ForEach(messages) { MessageRow($0).id($0.id) }
        }
    }
    .onChange(of: latestID) {
        withAnimation { proxy.scrollTo(latestID, anchor: .bottom) }
    }
}

@State private var sortOrder = [KeyPathComparator(\Person.name)]

